-- ----------------------------------------------------------------------------
-- Policies: A coverage agreement. Whether a policy is active is a fact about the policy (ground truth), recorded by the system — not a derived rule.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS policies (
  policy_id                           TEXT                 PRIMARY KEY          -- Stable identifier for the policy.
);
ALTER TABLE policies ADD COLUMN IF NOT EXISTS policyholder_name TEXT;                               -- Name of the policyholder.
ALTER TABLE policies ADD COLUMN IF NOT EXISTS is_active BOOLEAN;                                    -- Ground truth: whether the policy is currently in force. Per R. Ross: being active is a business STATE — a fact about the policy — not a derived business rule. The system's 'Is Active' indicator merely records this fact, so it lives at the leaves, not in a rule.
COMMENT ON TABLE policies IS 'A coverage agreement. Whether a policy is active is a fact about the policy (ground truth), recorded by the system — not a derived rule.';
COMMENT ON COLUMN policies.policy_id IS 'Stable identifier for the policy.';
COMMENT ON COLUMN policies.policyholder_name IS 'Name of the policyholder.';
COMMENT ON COLUMN policies.is_active IS 'Ground truth: whether the policy is currently in force. Per R. Ross: being active is a business STATE — a fact about the policy — not a derived business rule. The system''s ''Is Active'' indicator merely records this fact, so it lives at the leaves, not in a rule.';

-- ----------------------------------------------------------------------------
-- Claimants: A person linked to incidents and (optionally) to claims. Carries a current policy, a favorite color, and a derived incident count.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS claimants (
  claimant_id                         TEXT                 PRIMARY KEY          -- Stable identifier for the claimant.
);
ALTER TABLE claimants ADD COLUMN IF NOT EXISTS claimant_name TEXT;                                  -- Display name of the claimant.
ALTER TABLE claimants ADD COLUMN IF NOT EXISTS favorite_color TEXT;                                 -- The claimant's favorite color (a single-select attribute).
ALTER TABLE claimants ADD COLUMN IF NOT EXISTS policy TEXT;                                         -- The claimant's current policy (foreign key to Policies).
COMMENT ON TABLE claimants IS 'A person linked to incidents and (optionally) to claims. Carries a current policy, a favorite color, and a derived incident count.';
COMMENT ON COLUMN claimants.claimant_id IS 'Stable identifier for the claimant.';
COMMENT ON COLUMN claimants.claimant_name IS 'Display name of the claimant.';
COMMENT ON COLUMN claimants.favorite_color IS 'The claimant''s favorite color (a single-select attribute).';
COMMENT ON COLUMN claimants.policy IS 'The claimant''s current policy (foreign key to Policies).';

-- ----------------------------------------------------------------------------
-- Incidents: An event or loss that can give rise to a claim. Each incident involves exactly one claimant of record at the incident level.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS incidents (
  incident_id                         TEXT                 PRIMARY KEY          -- Stable identifier for the incident.
);
ALTER TABLE incidents ADD COLUMN IF NOT EXISTS incident_description TEXT;                           -- Short description of the incident.
ALTER TABLE incidents ADD COLUMN IF NOT EXISTS claimant TEXT;                                       -- The claimant involved in this incident (foreign key to Claimants via ClaimantId).
COMMENT ON TABLE incidents IS 'An event or loss that can give rise to a claim. Each incident involves exactly one claimant of record at the incident level.';
COMMENT ON COLUMN incidents.incident_id IS 'Stable identifier for the incident.';
COMMENT ON COLUMN incidents.incident_description IS 'Short description of the incident.';
COMMENT ON COLUMN incidents.claimant IS 'The claimant involved in this incident (foreign key to Claimants via ClaimantId).';

-- ----------------------------------------------------------------------------
-- Claims: A request to have an incident evaluated under a policy. Validity and approvability are computed, never entered.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS claims (
  claim_id                            TEXT                 PRIMARY KEY          -- Stable identifier for the claim.
);
ALTER TABLE claims ADD COLUMN IF NOT EXISTS incident TEXT;                                          -- The incident this claim references (exactly one; foreign key to Incidents via IncidentId).
ALTER TABLE claims ADD COLUMN IF NOT EXISTS additional_claimant TEXT;                               -- An optional second claimant linked to the same claim (foreign key to Claimants via ClaimantId).
ALTER TABLE claims ADD COLUMN IF NOT EXISTS is_flagged_for_review BOOLEAN;                          -- Ground truth: whether the claim has been flagged for manual review (e.g., possible fraud). A claim can be valid yet still be held here — which is exactly why 'approvable' is 'only if valid', not 'iff valid'.
COMMENT ON TABLE claims IS 'A request to have an incident evaluated under a policy. Validity and approvability are computed, never entered.';
COMMENT ON COLUMN claims.claim_id IS 'Stable identifier for the claim.';
COMMENT ON COLUMN claims.incident IS 'The incident this claim references (exactly one; foreign key to Incidents via IncidentId).';
COMMENT ON COLUMN claims.additional_claimant IS 'An optional second claimant linked to the same claim (foreign key to Claimants via ClaimantId).';
COMMENT ON COLUMN claims.is_flagged_for_review IS 'Ground truth: whether the claim has been flagged for manual review (e.g., possible fraud). A claim can be valid yet still be held here — which is exactly why ''approvable'' is ''only if valid'', not ''iff valid''.';

